# פרק 14 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=14
TITLE='פיצויים בנזיקין'
SUM=[' <p>שלב חישוב הסעד לאחר שנקבעה האחריות. העיקרון: <strong>השבת המצב לקדמותו</strong> (<strong>סעיף 76</strong>).</p> <h3>14.1 עקרון הפיצוי</h3> <p>להעמיד את הניזוק, ככל שהכסף מאפשר, במצב שבו היה אלמלא העוולה. הפיצוי ככלל <strong>חד-פעמי וגלובלי</strong>.</p> <h3>14.2 ראשי נזק</h3> <p><strong>ממוניים</strong>: הוצאות (רפואיות, נסיעות, עזרת צד ג\'), הפסד השתכרות בעבר ו<strong>אובדן כושר השתכרות</strong> בעתיד (חישוב אקטוארי). <strong>לא-ממוניים</strong>: כאב וסבל, קיצור תוחלת חיים, ופגיעה באוטונומיה (דעקה).</p> <h3>14.3 חישוב והפחתות</h3> <p>מהפיצוי מנכים <strong>אשם תורם</strong> (<strong>סעיף 68</strong>), גמלאות ותשלומים חופפים, ומיישמים <strong>היוון</strong> לפיצוי עתידי. נדרשת הוכחת הנזק והקשר הסיבתי.</p> <h3>14.4 נקודות מפתח למבחן</h3> <ul><li>השבת המצב לקדמותו (ס׳ 76); פיצוי גלובלי.</li><li>ראשי נזק ממוניים ולא-ממוניים.</li><li>ניכוי אשם תורם (ס׳ 68), גמלאות חופפות, והיוון.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[("ס' 76 לפקודת הנזיקין — עקרון הפיצוי", '', 'השבת המצב לקדמותו — העמדת הניזוק במצב שבו היה אלמלא העוולה, ככל שהכסף מאפשר.'), ('ראשי נזק', '', 'ממוניים (הוצאות, אובדן כושר השתכרות) ולא-ממוניים (כאב וסבל, קיצור תוחלת חיים, פגיעה באוטונומיה).'), ('ניכויים והיוון', '', 'ניכוי אשם תורם וגמלאות חופפות, והיוון הפיצוי העתידי לערך נוכחי — לפיצוי גלובלי הוגן.'), ('ע״א 357/80 נעים נ׳ ברדה, פ״ד לו(3) 762', 'ערעור שעסק בשומת פיצויים בגין נזקי גוף.', 'בית המשפט הציג את עקרון היסוד של שומת הנזק: "מטרת הפיצוי היא השבת המצב לקדמותו. אין הפיצוי בא להעניש את המזיק". הפיצוי אינו ביטוי לאהדה לניזוק. ביסודו עומד הנזק, ואותו יש להעריך ולכמת.'), ('ד״נ 24/81 חנוביץ נ׳ כהן, פ״ד לח(1) 413', 'דיון נוסף שעסק בשומת פיצויים ובהשפעת תשלומים שקיבל הניזוק ממקור אחר על הפיצוי מהמזיק.', 'נקבע שהמזיק "משלם את מלוא הנזק, ולא למעלה ממנו", ושהניזוק "אינו מקבל פיצוי כפול". מכאן נגזרת הגישה לניכוי טובות הנאה מהפיצוי כשאין חובת השבה, וזו התשתית לדיני ההטבה והניכויים.'), ('ע״א 140/00 עזבון אטינגר נ׳ החברה לשיקום ופיתוח הרובע היהודי, פ״ד נח(4) 486', 'נער בן 12 שיחק באתר משחקים ברובע היהודי בירושלים, נפל לבור לא מגודר שבתחתיתו משטח בטון, ונפטר למחרת. נקבע שהחברה האחראית לאתר התרשלה.', 'העליון הכיר בזכות העיזבון לפיצוי על הפסד ההשתכרות בשנים האבודות, גם של נפגע שנפטר וגם של קטין, בניכוי הוצאות הקיום של המנוח עצמו. ההכרה נועדה שלא יהיה זול יותר להמית מאשר לפצוע. בפסק הדין נאמר גם שבית המשפט מוסמך לפסוק פיצויים עונשיים בנסיבות מתאימות, בעיקר בעוולות זדון.'), ('ע״א 9656/03 עזבון מרציאנו נ׳ זינגר', 'אישה נפטרה מסרטן שאובחן באיחור, כי לא בוצעו בדיקות שהיו מגלות את המחלה מוקדם יותר. נקבע שהרופאים התרשלו (פסק הדין ניתן ב־2005).', 'נדחתה הבקשה לפסוק פיצויים עונשיים. פיצויים כאלה נועדו לעונש ולהרתעה, והם מוצדקים רק במקרים חמורים, מקוממים ומעוררי סלידה, ובפרט כשיש בהם כוונה. ברשלנות גרידא אין להם מקום.'), ('ע״א 5557/95 אלחדד נ׳ סהר, פ״ד נא(2) 724', 'דיון בשאלה אם נפגע שקיבל טיפול רפואי בחינם מקופת החולים, מכוח הדין, רשאי לתבוע מהמזיק את עלות הטיפולים.', 'נפגע שמקבל שירותים רפואיים בחינם מכוח החוק, ואינו חייב להשיב אותם, אינו זכאי לתבוע מהמזיק את עלותם. אחרת יקבל פיצוי כפל. הקופה, כמיטיבה, היא שזכאית לחזור אל המזיק. המבחן הוא קיומה של חובת השבה למיטיב.'), ('ע״א 163/99 עיזבון מזאווי נ׳ דורי, פ״ד נד(5)', 'אישה סעדה את בעלה שנפגע ממעשה נזיקין. הבעל נפטר לפני ששולמו הפיצויים, ועלו שאלות בדבר זכותה כמיטיבה ובדבר ניכוי גמלאות.', 'עזרה שבני משפחה נותנים לנפגע בחסד אינה פוטרת את המזיק. שוויה הוא נזק בר פיצוי, ובמקרה זה הוכרה זכותה של האישה כמיטיבה. ההטבה נועדה להיטיב עם הנפגע ולא עם המזיק.')]
QS=[{'q': 'מהו העיקרון המרכזי שמנחה את שומת הפיצויים בנזיקין בישראל?', 'o': ['ענישת המזיק לפי חומרת אשמו', 'השבת המצב לקדמותו — העמדת הניזוק, ככל שאפשר בכסף, במצב שבו היה אלמלא העוולה', 'פיצוי לפי יכולתו הכלכלית של המזיק', 'פיצוי אחיד לכל סוג פגיעה, לפי טבלה קבועה'], 'c': 1, 'e': 'נכון. זו הלכת נעים נ׳ ברדה וחנוביץ: פיצוי מלא, אבל לא יותר מהנזק.'}, {'q': 'מה ההבדל בין "נזק מיוחד" ל"נזק כללי"?', 'o': ['נזק מיוחד הוא נזק גוף, ונזק כללי הוא נזק רכוש', 'נזק מיוחד הוא הפסד ממוני שהתגבש וניתן לחישוב מדויק, ויש לפרטו ולהוכיחו. נזק כללי מוערך על ידי בית המשפט', 'אין הבדל מעשי בין השניים', 'נזק מיוחד הוא נזק שנגרם בזדון, ונזק כללי ברשלנות'], 'c': 1, 'e': 'נכון. ס׳ 76(2) מחייב פירוט של נזק ממון בכתב התביעה. נזק כללי (כאב וסבל, נזקים עתידיים) נקבע באומדן.'}, {'q': 'פקיד שנפגע בתאונה חזר לעבודתו באותו שכר, אך נותרה לו נכות שמגבילה את סיכויי הקידום ומגבירה את הסיכון שיפוטר. האם הוא זכאי לפיצוי על אובדן כושר השתכרות?', 'o': ['לא, כי שכרו לא נפגע', 'כן, אובדן כושר השתכרות עוסק בפוטנציאל העתידי, ובמקרה כזה נפסק לרוב סכום גלובלי', 'כן, אבל רק אם יפוטר בפועל', 'לא, כי מדובר בנזק לא ממוני'], 'c': 1, 'e': 'נכון. מצב של אי־ודאות לגבי ההשפעה העתידית מצדיק לרוב פיצוי גלובלי על הפגיעה בכושר.'}, {'q': 'שני נפגעים איבדו אצבע באותה יד ונקבעה להם אותה נכות רפואית. האחד פסנתרן מקצועי והשני רואה חשבון. כיצד יחושב אובדן כושר ההשתכרות?', 'o': ['באופן זהה, כי הנכות הרפואית זהה', 'לפי השכר הממוצע במשק לשניהם', 'לפי הנכות התפקודית, שנקבעת על ידי בית המשפט לפי השפעת הנכות על עבודתו של כל אחד', 'רק לפי הנכות שקבע המוסד לביטוח לאומי'], 'c': 2, 'e': 'נכון. הנכות התפקודית אצל הפסנתרן גבוהה בהרבה, ובהתאם גם הפיצוי.'}, {'q': 'ילד בן 8 נפגע ונותרה לו נכות צמיתה. מהו בסיס השכר המקובל לחישוב אובדן כושר השתכרותו?', 'o': ['אין פיצוי, כי הוא אינו עובד', 'שכר הוריו', 'השכר הממוצע במשק, אלא אם יש ראיה של ממש לפוטנציאל אחר', 'שכר המינימום'], 'c': 2, 'e': 'נכון. הפסיקה נוהגת להניח לקטינים בסיס של השכר הממוצע, כדי לא להנציח פערים חברתיים (ע״א 10064/02 מגדל נ׳ אבו חנא).'}, {'q': 'מדוע מהוונים פיצויים על הפסדים עתידיים?', 'o': ['כי המזיק זכאי להנחה על תשלום מוקדם', 'כי הסכום משולם היום בבת אחת ויכול להניב פירות, ולכן פיצוי מלא שווה לערך הנוכחי של זרם ההפסדים', 'כדי להעניש את הניזוק על התביעה', 'כי הפסדים עתידיים אינם בני פיצוי, וההיוון הוא פשרה'], 'c': 1, 'e': 'נכון. בלי היוון הניזוק היה מקבל יותר מהנזק. בפסיקה מקובלת ריבית היוון ריאלית של 3%.'}, {'q': 'נפגעת קיבלה טיפול צמוד של בעלה בחינם במשך שנה. המזיק טוען שאין לפצות על עזרת צד שלישי כי לא שולם דבר. מה הדין?', 'o': ['טענת המזיק נכונה, כי לא נגרם הפסד ממוני', 'מפצים רק מחצית מהשווי', 'מפצים רק אם הבעל עזב את עבודתו', 'הטענה נדחית. עזרה בחסד של בני משפחה אינה פוטרת את המזיק, ושוויה מפוצה'], 'c': 3, 'e': 'נכון. ראו עיזבון מזאווי נ׳ דורי: שווי העזרה מוכר, גם כשניתנה בלי תמורה.'}, {'q': 'נפגע תובע את עלות הניתוחים שעבר. הניתוחים מומנו במלואם על ידי קופת החולים במסגרת סל הבריאות. מה הדין?', 'o': ['הוא אינו זכאי לתבוע רכיב זה. הקופה היא שזכאית לחזור אל המזיק', 'הוא זכאי לסכום, כי זה נזק שנגרם לו', 'הוא זכאי למחצית מהסכום', 'הקופה והנפגע זכאים שניהם לכל הסכום'], 'c': 0, 'e': 'נכון. זו הלכת אלחדד נ׳ סהר: שירות רפואי בחינם מכוח החוק אינו נתבע על ידי הנפגע. המיטיבה היא שחוזרת אל המזיק.'}, {'q': 'נפגע רכש לפני התאונה פוליסת ביטוח תאונות אישיות וקיבל ממנה תגמולים. המזיק מבקש לנכות אותם מהפיצוי. מה הדין?', 'o': ['מנכים מחצית', 'לא מנכים — ס׳ 86 לפקודה קובע שסכום מחוזה ביטוח לא יובא בחשבון בשומת הפיצויים', 'מנכים במלואם', 'מנכים רק אם המבטח תבע את המזיק'], 'c': 1, 'e': 'נכון. הנפגע "קנה" את ההגנה בכספו, ואין סיבה שהמזיק ייהנה ממנה.'}, {'q': 'מה פסק העליון בעניין אטינגר בשאלת "השנים האבודות"?', 'o': ['העיזבון זכאי לפיצוי על הפסד ההשתכרות בשנים האבודות, גם של נפטר וגם של קטין, בניכוי הוצאות הקיום של המנוח', 'השנים האבודות מפוצות רק כשהמנוח היה מעל גיל 18 ועבד', 'השנים האבודות מפוצות רק לתלויים, ולא לעיזבון', 'אין פיצוי על שנים אבודות לנפגע שנפטר'], 'c': 0, 'e': 'נכון. הנימוק: לא ייתכן שיהיה זול יותר להמית מאשר לפצוע. מנכים את צריכתו העצמית של המנוח.'}, {'q': 'אלמנתו של אדם שנהרג בעוולה תובעת לפי ס׳ 78 לפקודה. על מה תפוצה בתביעה זו?', 'o': ['על צערה ואבלה', 'על כל ראשי הנזק של המנוח עצמו', 'על הכאב והסבל של המנוח לפני מותו', 'על הפסד הממון שסבלה ושתסבול בשל אובדן התמיכה, וכן הוצאות קבורה'], 'c': 3, 'e': 'נכון. זו לשון ס׳ 80: "הפסד הממון שסבלו למעשה, או עתידים לסבול אותו למעשה, ובכלל זה הוצאות שהוציאו לקבורתו".'}, {'q': 'מנוח הותיר אחריו פוליסת ביטוח חיים, ובני משפחתו קיבלו ממנה סכום גבוה. המזיק מבקש להפחית את פיצויי התלויים. מה הדין?', 'o': ['מפחיתים את מלוא הסכום', 'מפחיתים רק אם המזיק שילם את הפרמיות', 'לא מפחיתים — לפי ס׳ 81 לא יובאו בחשבון סכומים לפי חוזה ביטוח במות המת', 'מפחיתים לפי שיקול דעת בית המשפט'], 'c': 2, 'e': 'נכון. ס׳ 81 מוציא מהחשבון סכום ביטוח שהתקבל במות המת וסכום ששולם לרגל האבל.'}, {'q': 'בתביעת רשלנות רפואית על אבחון מאוחר שגרם למוות, ביקשו התובעים גם פיצויים עונשיים. מה ההלכה לפי עניין מרציאנו?', 'o': ['פיצויים עונשיים נפסקים בכל רשלנות רפואית חמורה', 'ברשלנות גרידא אין מקום לפיצויים עונשיים. הם שמורים למקרים חמורים ומקוממים, בעיקר כשיש כוונה', 'פיצויים עונשיים אסורים בישראל בכל מקרה', 'פיצויים עונשיים נפסקים רק נגד גופים ציבוריים'], 'c': 1, 'e': 'נכון. פיצויים עונשיים הם חריג ששמור לעוולות זדון ולהתנהגות מעוררת סלידה.'}, {'q': 'מה ההבדל בין פיצויים מוגברים לפיצויים עונשיים?', 'o': ['פיצויים מוגברים מפצים על נזק לא ממוני שהוחמר בשל התנהגות המזיק, ופיצויים עונשיים נועדו להעניש מעבר לנזק', 'פיצויים עונשיים מפצים על נזק ממוני, ומוגברים על נזק רכוש', 'פיצויים מוגברים ניתנים רק בתאונות דרכים', 'אין הבדל, אלה שני שמות לאותו דבר'], 'c': 0, 'e': 'נכון. מוגברים הם הערכה כנה של נזק לא ממוני שהתנהגות המזיק העצימה. עונשיים חורגים מהנזק.'}, {'q': 'שני קבלנים התרשלו יחד וגרמו לנזק של מיליון ש״ח. אחד מהם חדל פירעון. ממי יכול הניזוק לגבות?', 'o': ['רק מהמדינה', 'מאף אחד, עד שיסתיים הליך חדלות הפירעון', 'את מלוא הסכום מהקבלן הסולבנטי, שיחזור על חברו לפי ס׳ 84', 'רק מחצית מכל אחד, ולכן יפסיד מחצית'], 'c': 2, 'e': 'נכון. לפי ס׳ 11 כל מעוול חב במלוא הנזק. הסיכון של חדלות פירעון עובר אל המעוול האחר, שיכול לתבוע השתתפות.'}, {'q': 'לפי ס׳ 84(ב) לפקודה, כיצד נקבעים דמי ההשתתפות בין מעוולים?', 'o': ['לפי היכולת הכלכלית של כל מעוול', 'תמיד בחלקים שווים', 'לפי סדר הגשת התביעות', 'על פי הצדק והיושר בהתחשב עם מידת אחריותו של כל אחד, ובית המשפט רשאי גם לפטור או להורות על שיפוי מלא'], 'c': 3, 'e': 'נכון. זו לשון ס׳ 84(ב): "על פי הצדק והיושר בהתחשב עם מידת אחריותו של האדם לנזק".'}, {'q': 'מה קובע ס׳ 76(2) לפקודת הנזיקין?', 'o': ['שהפיצוי מוגבל לשווי הנכס ביום העוולה', 'שפיצויים יינתנו רק בתשלומים עיתיים', 'שלא יינתנו פיצויים על נזק ממון אלא אם נמסרו פרטים עליו בכתב התביעה או בצירוף לו', 'שאין לפצות על נזק לא ממוני'], 'c': 2, 'e': 'נכון. זו הדרישה הפרוצדורלית־מהותית לפרט נזק מיוחד.'}, {'q': 'מה קובע ס׳ 77(א) לפקודה?', 'o': ['שפיצויים ניתנים רק בכסף', 'שאין לתבוע בעילה חוזית ובעילה נזיקית באותו כתב תביעה', 'שאדם שנפרע פיצויים בשל עוולה לא ייפרע פיצויים נוספים בשל אותה עוולה', 'שכל ניזוק זכאי לפיצוי כפול כשיש שני מזיקים'], 'c': 2, 'e': 'נכון. זה עיגון חוקי לאיסור הכפל ולכלל "פעם אחת" (בכפוף לס׳ 83–85).'}, {'q': 'נפגע עם נכות תפקודית של 40% ושכר בסיס של 10,000 ש״ח, ו־20 שנה עד גיל הפרישה. סטודנט חישב: 4,000 × 12 × 20 = 960,000 ש״ח. מה הבעיה העיקרית בחישוב?', 'o': ['היה עליו לחשב עד גיל 80', 'היה עליו להכפיל בנכות הרפואית ולא בתפקודית', 'הוא לא היוון את ההפסד העתידי לערך נוכחי, ולכן הסכום גבוה מהנזק האמיתי', 'הוא שכח להוסיף פיצויים עונשיים'], 'c': 2, 'e': 'נכון. בלי היוון (3%) הניזוק מקבל סכום שיכול להניב פירות, כלומר יותר מהנזק.'}, {'q': 'ניזוק נמצא אחראי ל־25% מנזקו בשל אשם תורם. כיצד פועל בית המשפט לפי ס׳ 68(ב)?', 'o': ['מבטל את ראשי הנזק הלא ממוניים בלבד', 'קובע ורושם את סך כל הפיצויים שהיו מגיעים אילולא האשם, ואז מפחית 25%', 'מעביר את 25% לתשלום על ידי המדינה', 'קובע מראש פיצוי של 75% בכל ראש נזק בלי לרשום את הסכום המלא'], 'c': 1, 'e': 'נכון. ס׳ 68(ב): "יקבע בית המשפט וירשום את סך כל הפיצויים שהתובע היה יכול להיפרע אילולא אשמו".'}, {'q': 'מהו עקרון הפיצוי בנזיקין?', 'o': ['ענישה', 'השבת המצב לקדמותו', 'רווח', 'הרתעה בלבד'], 'c': 1, 'e': "ס' 76."}, {'q': 'איזה ראש נזק הוא ממוני?', 'o': ['כאב וסבל', 'אובדן כושר השתכרות', 'פגיעה באוטונומיה', 'קיצור תוחלת חיים'], 'c': 1, 'e': 'נזק כספי מדיד.'}, {'q': 'כאב וסבל הוא:', 'o': ['ראש נזק ממוני', 'ראש נזק לא-ממוני', 'ניכוי', 'גמלה'], 'c': 1, 'e': 'נפסק לפי אומדן.'}, {'q': 'מה מנכים מהפיצוי?', 'o': ['אשם תורם וגמלאות חופפות', 'ריבית בלבד', 'מס בלבד', 'דבר'], 'c': 0, 'e': 'מניעת פיצוי-יתר.'}, {'q': 'מהו "היוון"?', 'o': ['הכפלת פיצוי', 'תרגום פיצוי עתידי לערך נוכחי', 'קנס', 'ריבית פיגורים'], 'c': 1, 'e': 'לפיצוי גלובלי חד-פעמי.'}]
